**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int freq[10] = {0};

    while (plik >> liczba) {
        while (liczba > 0) {
            freq[liczba % 10]++;
            liczba /= 10;
        }
    }

    cout << "a) Tablica czestotliwosci cyfr:" << endl;
    int lacznie = 0;
    for (int i = 0; i < 10; i++) {
        cout << "cyfra " << i << ": " << freq[i] << endl;
        lacznie += freq[i];
    }

    cout << endl << "b) Lacznie cyfr: " << lacznie << endl;

    int maxCyfra = 0, minCyfra = 0;
    for (int i = 1; i < 10; i++) {
        if (freq[i] > freq[maxCyfra]) maxCyfra = i;
        if (freq[i] < freq[minCyfra]) minCyfra = i;
    }

    cout << endl << "c) Najczestsza cyfra: " << maxCyfra
         << " (" << freq[maxCyfra] << " razy)" << endl;
    cout << endl << "d) Najrzadsza cyfra: " << minCyfra
         << " (" << freq[minCyfra] << " razy)" << endl;
    return 0;
}
```

**Wyjasnienie**: Tablica `freq[10]` zlicza wystapienia kazdej cyfry (0-9) we wszystkich liczbach. Iterujac od 0 do 9, przy remisie natural wybieramy najmniejsza cyfre (bo `>` i `<` nie aktualizuja przy rownosci). Uwaga: petla `while(liczba > 0)` nie zlicza wiodacych zer — ale 0 jako cyfra wewnatrz liczby (np. 9901) jest prawidlowo zliczona.

